@compute @workgroup_size(256, 1, 1)
fn scatter(@builtin(global_invocation_id) gid: vec3<u32>, @builtin(local_invocation_id) lid: vec3<u32>, @builtin(workgroup_id) wid: vec3<u32>, @builtin(local_invocation_index) lidx: u32, @builtin(num_workgroups) nwg: vec3<u32>) {
const KNOB_WCOL: u32 = 256u; const KNOB_WROW: u32 = 1u; const KNOB_BCOL: u32 = 1u; const KNOB_BROW: u32 = 1u; const KNOB_KTILE: u32 = 1u; const KNOB_THREADS: u32 = 256u * 1u;

var<workgroup> sh_a: array<u32, 256>;

fn nblocks() -> u32 { return (params.x + 255u) / 256u; }
// scratch layout: [0, nb*k) per-(block,cluster) counts (block-major),
// then k totals, then k starts, then n sorted point indices.
fn scratch_ok() -> bool {
  let nb = nblocks();
  return arrayLength(&scratch) >= nb * params.y + 2u * params.y + params.x;
}

@compute @workgroup_size(256, 1, 1)
fn hist(@builtin(global_invocation_id) gid: vec3<u32>, @builtin(local_invocation_id) lid: vec3<u32>, @builtin(workgroup_id) wid: vec3<u32>, @builtin(local_invocation_index) lidx: u32, @builtin(num_workgroups) nwg: vec3<u32>) {
  let k = params.y;
  let nb = nblocks();
  let g = gid.x;
  if (g >= nb * k || !scratch_ok()) { return; }
  let b = g / k;
  let c = g % k;
  let base = b * 256u;
  let end = min(base + 256u, params.x);
  var cnt: u32 = 0u;
  for (var q: u32 = 0u; q < 256u; q = q + 1u) {
    let idx = base + q;
    if (idx >= end) { break; }
    if (assignments[idx] == c) { cnt = cnt + 1u; }
  }
  scratch[g] = cnt;
}

@compute @workgroup_size(256, 1, 1)
fn offsets(@builtin(global_invocation_id) gid: vec3<u32>, @builtin(local_invocation_id) lid: vec3<u32>, @builtin(workgroup_id) wid: vec3<u32>, @builtin(local_invocation_index) lidx: u32, @builtin(num_workgroups) nwg: vec3<u32>) {
  let k = params.y;
  let c = gid.x;
  if (c >= k || !scratch_ok()) { return; }
  let nb = nblocks();
  var run: u32 = 0u;
  for (var b: u32 = 0u; b < 4096u; b = b + 1u) {
    if (b >= nb) { break; }
    let v = scratch[b * k + c];
    scratch[b * k + c] = run;
    run = run + v;
  }
  scratch[nb * k + c] = run;
}

@compute @workgroup_size(256, 1, 1)
fn starts(@builtin(global_invocation_id) gid: vec3<u32>, @builtin(local_invocation_id) lid: vec3<u32>, @builtin(workgroup_id) wid: vec3<u32>, @builtin(local_invocation_index) lidx: u32, @builtin(num_workgroups) nwg: vec3<u32>) {
  if (lidx != 0u || !scratch_ok()) { return; }
  let k = params.y;
  let nb = nblocks();
  let cb = nb * k;
  var run: u32 = 0u;
  for (var c: u32 = 0u; c < k; c = c + 1u) {
    let v = scratch[cb + c];
    scratch[cb + k + c] = run;
    run = run + v;
  }
}

@compute @workgroup_size(64, 2, 1)
fn scatter(@builtin(global_invocation_id) gid: vec3<u32>, @builtin(local_invocation_id) lid: vec3<u32>, @builtin(workgroup_id) wid: vec3<u32>, @builtin(local_invocation_index) lidx: u32, @builtin(num_workgroups) nwg: vec3<u32>) {
const KNOB_WCOL: u32 = 64u; const KNOB_WROW: u32 = 2u; const KNOB_BCOL: u32 = 1u; const KNOB_BROW: u32 = 1u; const KNOB_KTILE: u32 = 1u; const KNOB_THREADS: u32 = 64u * 2u;

{ let cs_n = params.x; let cs_k = params.y; let cs_w = wid.x; let cs_b = cs_w / 2u;
let cs_a0 = cs_b * 256u + lidx; let cs_a1 = cs_a0 + 128u;
sh_a[lidx] = select(0xffffffffu, assignments[min(cs_a0, arrayLength(&assignments) - 1u)], cs_a0 < cs_n);
sh_a[lidx + 128u] = select(0xffffffffu, assignments[min(cs_a1, arrayLength(&assignments) - 1u)], cs_a1 < cs_n);
workgroupBarrier();
cs_v = cs_w * 128u + lidx;
if (cs_v >= cs_n || !scratch_ok()) { return; }
let cs_p = (cs_w & 1u) * 128u + lidx;
cs_a = sh_a[cs_p];
if (cs_a >= cs_k) { return; }
cs_ok = true;
var cs_rank: u32 = 0u;
for (var cs_q: u32 = 0u; cs_q < 256u; cs_q = cs_q + 1u) { if (cs_q >= cs_p) { break; } if (sh_a[cs_q] == cs_a) { cs_rank = cs_rank + 1u; } }
let cs_cb = nblocks() * cs_k;
cs_slot = cs_cb + 2u * cs_k + scratch[cs_cb + cs_k + cs_a] + scratch[cs_b * cs_k + cs_a] + cs_rank;
}

