let cs_st7_s4: u32 = (cs_st7_s0 % cs_st7_s2);
if ((cs_st7_s0 >= (((cs_st7_s1 + 255u) / lit_u32(256u)) * cs_st7_s2))) { {} } else { nx1 = min(lit_u32(256u), 4096u); kxc1 = 0u; loop { kx1 = kxc1; if (kx1 >= nx1) { break; } kxc1 = kx1 + 1u; if (((cs_st7_s3 + kx1) < cs_st7_s1)) { if ((assignments[min((cs_st7_s3 + kx1), arrayLength(&assignments) - 1u)] == cs_st7_s4)) { ru0 = (ru0 + 1u); } } } ru1 = kx1; { let i = cs_st7_s0; scratch[min(i, arrayLength(&scratch) - 1u)] = ru0; } }
}

